mapper.select:
select a.id,a.policy_code policyCode,a.proj_id projId,b.proj_name projName,b.client_id clientId,
a.insurance_start_date insuranceStartDate,a.insurance_end_date insuranceEndDate,
a.insurance_company insuranceCompany,b.proj_sponsor_user_id projSponsorUserId,
b.proj_cosponsor_user_ids projCosponsorUserIds,a.approval_status approvalStatus,
a.create_time createTime,a.update_time updateTime
from policy_info a,proj_review_base_info b

    a.proj_id = b.id
    and b.client_id = #{req.clientId}
    and a.insurance_company LIKE concat('%', #{req.insuranceCompany},'%')
    and b.proj_name LIKE concat('%', #{req.projName},'%')
    and a.policy_code LIKE concat('%', #{req.policyCode},'%')
    and a.insurance_start_date  >=  #{req.insuranceStartDateFrom}
    and a.insurance_start_date  <=  #{req.insuranceStartDateTo}
    and a.insurance_end_date  >=  #{req.insuranceEndDateFrom}
    and a.insurance_end_date  <=  #{req.insuranceEndDateTo}
    and b.proj_sponsor_user_id = #{req.projSponsorUserId}
    and a.approval_status = #{req.approvalStatus}
    
        and json_contains(b.proj_cosponsor_user_ids, CONVERT(#{req.projCosponsorUserId},CHAR))
    

order by a.update_time desc

